"""Pydantic models for configuration and runtime state."""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, Field, field_validator


class TargetConfig(BaseModel):
    url: str
    allowed_hosts: list[str] = Field(default_factory=lambda: ["xindai.duxiaoman.com"])


class SafetyConfig(BaseModel):
    max_concurrency: int = 50
    max_qps: float = 20.0
    max_duration_seconds: int = 60
    max_requests: int = 1000
    stop_on_429_ratio: float = 0.3
    stop_on_403_ratio: float = 0.3
    stop_on_5xx_ratio: float = 0.2
    allow_mutation_requests: bool = False
    allow_load_test: bool = False

    @field_validator("max_concurrency")
    @classmethod
    def concurrency_positive(cls, v: int) -> int:
        if v < 1:
            raise ValueError("max_concurrency must be >= 1")
        if v > 1000:
            raise ValueError("max_concurrency cannot exceed 1000")
        return v

    @field_validator("max_qps")
    @classmethod
    def qps_positive(cls, v: float) -> float:
        if v <= 0:
            raise ValueError("max_qps must be > 0")
        return v

    @field_validator("max_duration_seconds", "max_requests")
    @classmethod
    def positive_int(cls, v: int) -> int:
        if v < 1:
            raise ValueError("must be >= 1")
        return v


class BrowserConfig(BaseModel):
    headless: bool = True
    record_network: bool = True
    record_console: bool = True
    record_storage: bool = False
    navigation_timeout_ms: int = 30000
    wait_after_load_ms: int = 3000


class HttpConfig(BaseModel):
    timeout_seconds: float = 15.0
    default_headers: dict[str, str] = Field(
        default_factory=lambda: {
            "User-Agent": "AntiBotTester/1.0 (authorized-security-test; mock-only)"
        }
    )


class MockServerConfig(BaseModel):
    host: str = "127.0.0.1"
    port: int = 8765
    base_url: str = "http://127.0.0.1:8765"


class TestDataConfig(BaseModel):
    environment: str = "mock"
    phone: str = "13800000000"
    id_card: str = "110101199001010000"
    bank_card: str = "6222000000000000000"
    name: str = "TEST_USER"
    address: str = "TEST_ADDRESS_ONLY"

    @field_validator("environment")
    @classmethod
    def must_be_mock(cls, v: str) -> str:
        if v != "mock":
            raise ValueError(
                f"test_data.environment must be 'mock' (got {v!r}). "
                "Refusing to run with non-mock test data."
            )
        return v


class ReportConfig(BaseModel):
    output_dir: str = "reports"
    generate_html: bool = True
    generate_json: bool = True
    generate_csv: bool = True


class AppConfig(BaseModel):
    mode: str = "SAFE_DISCOVERY"
    target: TargetConfig
    safety: SafetyConfig = Field(default_factory=SafetyConfig)
    browser: BrowserConfig = Field(default_factory=BrowserConfig)
    http: HttpConfig = Field(default_factory=HttpConfig)
    mock_server: MockServerConfig = Field(default_factory=MockServerConfig)
    test_data: TestDataConfig = Field(default_factory=TestDataConfig)
    report: ReportConfig = Field(default_factory=ReportConfig)

    @field_validator("mode")
    @classmethod
    def mode_valid(cls, v: str) -> str:
        allowed = {"SAFE_DISCOVERY", "LOAD_TEST"}
        if v not in allowed:
            raise ValueError(f"mode must be one of {allowed}, got {v!r}")
        return v

    def model_post_init(self, __context: Any) -> None:
        # LOAD_TEST mode requires explicit allow_load_test flag
        if self.mode == "LOAD_TEST" and not self.safety.allow_load_test:
            raise ValueError(
                "mode=LOAD_TEST requires safety.allow_load_test=true"
            )

"""Target URL allowlist and SSRF protection."""

from __future__ import annotations

import ipaddress
import re
from urllib.parse import urlparse

from app.constants import (
    ALLOWED_SCHEMES_REAL_TARGET,
    BLOCKED_HOSTNAMES,
    BLOCKED_SCHEMES,
    DEFAULT_ALLOWED_HOSTS,
)
from app.models import AppConfig


class TargetGuardError(Exception):
    """Raised when a target URL is not permitted."""


_IPV4_RE = re.compile(r"^\d{1,3}(?:\.\d{1,3}){3}$")


class TargetGuard:
    """Validate that traffic only goes to authorized hosts.

    Real-target rules (default):
    - https only
    - host must be in allowed_hosts (default: xindai.duxiaoman.com)
    - block localhost / private IPs / cloud metadata / file/ftp/etc.

    Mock-server exceptions are handled separately via allow_mock=True.
    """

    def __init__(self, config: AppConfig | None = None) -> None:
        if config is None:
            self.allowed_hosts = set(DEFAULT_ALLOWED_HOSTS)
            self.mock_base_url: str | None = None
        else:
            self.allowed_hosts = {h.lower() for h in config.target.allowed_hosts}
            self.mock_base_url = config.mock_server.base_url.rstrip("/")

    def assert_allowed(self, url: str, *, allow_mock: bool = False) -> None:
        ok, reason = self.check(url, allow_mock=allow_mock)
        if not ok:
            raise TargetGuardError(reason)

    def check(self, url: str, *, allow_mock: bool = False) -> tuple[bool, str]:
        if not url or not isinstance(url, str):
            return False, "Target URL is empty"

        parsed = urlparse(url.strip())
        scheme = (parsed.scheme or "").lower()
        host = (parsed.hostname or "").lower()

        if not scheme:
            return False, f"Missing URL scheme: {url!r}"

        if scheme in BLOCKED_SCHEMES:
            return False, f"Blocked scheme '{scheme}': {url}"

        if allow_mock and self._is_mock_url(url):
            return True, "ok-mock"

        if scheme not in ALLOWED_SCHEMES_REAL_TARGET:
            return False, (
                f"Real target must use https (got '{scheme}'). "
                "Use Mock Server for local attack scenarios."
            )

        if not host:
            return False, f"Missing hostname: {url}"

        if host in BLOCKED_HOSTNAMES:
            return False, f"Blocked hostname '{host}' (SSRF protection)"

        if host.endswith(".internal") or host.endswith(".localhost"):
            return False, f"Blocked internal hostname '{host}'"

        # Cloud metadata aliases
        if "metadata" in host and (
            "google" in host or "aws" or "alibaba" in host or "169.254.169.254" in url
        ):
            # Keep simple: any *metadata* host is blocked for real targets
            if "metadata" in host:
                return False, f"Blocked metadata hostname '{host}'"

        if self._is_ip_literal(host):
            if self._is_dangerous_ip(host):
                return False, f"Blocked IP address '{host}' (SSRF protection)"
            return False, (
                f"Direct IP targets are not allowed ('{host}'). "
                "Use an allowlisted hostname."
            )

        if host not in self.allowed_hosts:
            return False, (
                f"Host '{host}' is not in allowed_hosts {sorted(self.allowed_hosts)}. "
                "Refusing to run against unauthorized target."
            )

        return True, "ok"

    def _is_mock_url(self, url: str) -> bool:
        if not self.mock_base_url:
            return False
        return url.rstrip("/").startswith(self.mock_base_url)

    @staticmethod
    def _is_ip_literal(host: str) -> bool:
        if _IPV4_RE.match(host):
            return True
        if ":" in host:  # likely IPv6
            try:
                ipaddress.ip_address(host)
                return True
            except ValueError:
                return False
        return False

    @staticmethod
    def _is_dangerous_ip(host: str) -> bool:
        try:
            ip = ipaddress.ip_address(host)
        except ValueError:
            return True
        return bool(
            ip.is_private
            or ip.is_loopback
            or ip.is_link_local
            or ip.is_reserved
            or ip.is_multicast
            or ip.is_unspecified
        )

"""Startup and runtime safety gates."""

from __future__ import annotations

from app.constants import (
    ALLOWED_SAFE_METHODS,
    MODE_LOAD_TEST,
    MODE_SAFE_DISCOVERY,
    MUTATION_METHODS,
)
from app.models import AppConfig
from app.target_guard import TargetGuard, TargetGuardError


class SafetyGuardError(Exception):
    """Raised when an operation violates safety policy."""


class SafetyGuard:
    """Enforce mock-only data, mutation locks, and load-test gates."""

    def __init__(self, config: AppConfig) -> None:
        self.config = config
        self.target_guard = TargetGuard(config)

    def assert_startup_safe(self) -> None:
        if self.config.test_data.environment != "mock":
            raise SafetyGuardError(
                "test_data.environment must be 'mock'. Refusing to start."
            )

        if self.config.mode == MODE_LOAD_TEST and not self.config.safety.allow_load_test:
            raise SafetyGuardError(
                "LOAD_TEST mode requires safety.allow_load_test=true"
            )

        # Hard caps — config may raise these, but double-check
        s = self.config.safety
        if s.max_concurrency > 1000:
            raise SafetyGuardError("max_concurrency cannot exceed 1000")
        if s.max_concurrency < 1 or s.max_qps <= 0:
            raise SafetyGuardError("Invalid rate limits")

    def assert_load_test_allowed(self) -> None:
        if not self.config.safety.allow_load_test:
            raise SafetyGuardError(
                "Load / pressure scenarios require safety.allow_load_test=true. "
                "Default mode is SAFE_DISCOVERY."
            )
        if self.config.mode != MODE_LOAD_TEST:
            raise SafetyGuardError(
                "Set mode: LOAD_TEST in config.yaml to run pressure scenarios."
            )

    def assert_method_allowed(self, method: str, *, to_real_target: bool = True) -> None:
        m = method.upper()
        if m in ALLOWED_SAFE_METHODS:
            return
        if m in MUTATION_METHODS:
            if to_real_target and not self.config.safety.allow_mutation_requests:
                raise SafetyGuardError(
                    f"{m} to real target is blocked "
                    "(safety.allow_mutation_requests=false)."
                )
            if to_real_target and not self.config.safety.allow_mutation_requests:
                raise SafetyGuardError(f"{m} not permitted")
            return
        raise SafetyGuardError(f"Unsupported HTTP method: {m}")

    def assert_url_for_request(
        self, url: str, *, use_mock: bool = False, method: str = "GET"
    ) -> None:
        try:
            self.target_guard.assert_allowed(url, allow_mock=use_mock)
        except TargetGuardError as exc:
            raise SafetyGuardError(str(exc)) from exc
        to_real = not use_mock
        self.assert_method_allowed(method, to_real_target=to_real)

    def is_safe_discovery_only(self) -> bool:
        return (
            self.config.mode == MODE_SAFE_DISCOVERY
            and not self.config.safety.allow_load_test
        )

    def max_concurrency_for_run(self) -> int:
        return self.config.safety.max_concurrency

    def max_qps_for_run(self) -> float:
        return float(self.config.safety.max_qps)

