"""TargetGuard focused tests."""

from __future__ import annotations

from pathlib import Path

import pytest

from app.config import load_config
from app.target_guard import TargetGuard, TargetGuardError

ROOT = Path(__file__).resolve().parents[1]


@pytest.fixture
def guard() -> TargetGuard:
    return TargetGuard(load_config(ROOT / "config.yaml"))


def test_https_allowed(guard: TargetGuard):
    guard.assert_allowed(
        "https://xindai.duxiaoman.com/umoney?tp=xh"
    )


def test_http_real_target_rejected(guard: TargetGuard):
    with pytest.raises(TargetGuardError, match="https"):
        guard.assert_allowed("http://xindai.duxiaoman.com/")


def test_wrong_subdomain_rejected(guard: TargetGuard):
    with pytest.raises(TargetGuardError):
        guard.assert_allowed("https://duxiaoman.com/")


def test_ssrf_ipv6_loopback(guard: TargetGuard):
    ok, _ = guard.check("https://[::1]/")
    assert not ok

