"""Record Playwright network / console / navigation events."""

from __future__ import annotations

import time
from typing import Any

from flow.flow_model import (
    ConsoleRecord,
    NavigationRecord,
    NetworkFlow,
    NetworkRequestRecord,
    PageErrorRecord,
)


class NetworkRecorder:
    """Attach to a Playwright page and capture traffic metadata.

    Does not click submit buttons or fill real PII forms.
    Response bodies are NOT stored raw (sensitive-data protection);
    only status / headers / size / timing are kept.
    """

    def __init__(self) -> None:
        self._pending: dict[str, dict[str, Any]] = {}
        self.requests: list[NetworkRequestRecord] = []
        self.console: list[ConsoleRecord] = []
        self.page_errors: list[PageErrorRecord] = []
        self.navigations: list[NavigationRecord] = []

    def attach(self, page: Any) -> None:
        page.on("request", self._on_request)
        page.on("response", self._on_response)
        page.on("requestfailed", self._on_request_failed)
        page.on("console", self._on_console)
        page.on("pageerror", self._on_page_error)
        page.on("framenavigated", self._on_frame_navigated)

    def _on_request(self, request: Any) -> None:
        key = id(request)
        headers = {}
        try:
            headers = {k: v for k, v in request.headers.items()}
        except Exception:
            headers = {}
        self._pending[key] = {
            "method": request.method,
            "url": request.url,
            "resource_type": getattr(request, "resource_type", None),
            "request_headers": headers,
            "started_at_ms": time.time() * 1000,
        }

    def _on_response(self, response: Any) -> None:
        request = response.request
        key = id(request)
        base = self._pending.pop(key, None) or {
            "method": request.method,
            "url": request.url,
            "resource_type": getattr(request, "resource_type", None),
            "request_headers": {},
            "started_at_ms": time.time() * 1000,
        }
        finished = time.time() * 1000
        started = base.get("started_at_ms") or finished
        resp_headers: dict[str, str] = {}
        try:
            resp_headers = {k: v for k, v in response.headers.items()}
        except Exception:
            pass
        size = None
        cl = resp_headers.get("content-length") or resp_headers.get("Content-Length")
        if cl and str(cl).isdigit():
            size = int(cl)
        self.requests.append(
            NetworkRequestRecord(
                method=base["method"],
                url=base["url"],
                status=response.status,
                resource_type=base.get("resource_type"),
                duration_ms=round(finished - started, 2),
                request_headers=base.get("request_headers") or {},
                response_headers=resp_headers,
                response_size=size,
                started_at_ms=started,
                finished_at_ms=finished,
            )
        )

    def _on_request_failed(self, request: Any) -> None:
        key = id(request)
        base = self._pending.pop(key, None) or {
            "method": request.method,
            "url": request.url,
            "resource_type": getattr(request, "resource_type", None),
            "request_headers": {},
            "started_at_ms": time.time() * 1000,
        }
        finished = time.time() * 1000
        started = base.get("started_at_ms") or finished
        failure = None
        try:
            failure = request.failure
        except Exception:
            failure = "requestfailed"
        self.requests.append(
            NetworkRequestRecord(
                method=base["method"],
                url=base["url"],
                status=None,
                resource_type=base.get("resource_type"),
                duration_ms=round(finished - started, 2),
                request_headers=base.get("request_headers") or {},
                failure=str(failure) if failure else "requestfailed",
                started_at_ms=started,
                finished_at_ms=finished,
            )
        )

    def _on_console(self, msg: Any) -> None:
        loc = None
        try:
            location = msg.location
            if location:
                loc = f"{location.get('url', '')}:{location.get('lineNumber', '')}"
        except Exception:
            pass
        text = msg.text
        # Truncate long console dumps; masking happens in later security phase
        if len(text) > 2000:
            text = text[:2000] + "...[truncated]"
        self.console.append(ConsoleRecord(type=msg.type, text=text, location=loc))

    def _on_page_error(self, exc: Any) -> None:
        self.page_errors.append(PageErrorRecord(message=str(exc)[:2000]))

    def _on_frame_navigated(self, frame: Any) -> None:
        try:
            if frame.parent_frame is not None:
                return
        except Exception:
            pass
        self.navigations.append(
            NavigationRecord(url=frame.url, timestamp_ms=time.time() * 1000)
        )

    def to_flow(
        self,
        *,
        target_url: str,
        final_url: str | None,
        started_at: str,
        finished_at: str,
        meta: dict[str, Any] | None = None,
    ) -> NetworkFlow:
        return NetworkFlow(
            target_url=target_url,
            final_url=final_url,
            started_at=started_at,
            finished_at=finished_at,
            requests=list(self.requests),
            navigations=list(self.navigations),
            console=list(self.console),
            page_errors=list(self.page_errors),
            meta=meta or {},
        )

"""Parse recorded flows into simplified request lists."""

from __future__ import annotations

from flow.flow_model import NetworkFlow, NetworkRequestRecord


class FlowParser:
    def safe_methods_only(self, flow: NetworkFlow) -> list[NetworkRequestRecord]:
        allowed = {"GET", "HEAD", "OPTIONS"}
        return [r for r in flow.requests if r.method.upper() in allowed]

    def xhr_and_fetch(self, flow: NetworkFlow) -> list[NetworkRequestRecord]:
        types = {"xhr", "fetch"}
        return [
            r
            for r in flow.requests
            if (r.resource_type or "").lower() in types
        ]

    def summary(self, flow: NetworkFlow) -> dict:
        by_status: dict[str, int] = {}
        by_type: dict[str, int] = {}
        for r in flow.requests:
            key = str(r.status) if r.status is not None else "failed"
            by_status[key] = by_status.get(key, 0) + 1
            t = r.resource_type or "unknown"
            by_type[t] = by_type.get(t, 0) + 1
        return {
            "total_requests": len(flow.requests),
            "by_status": by_status,
            "by_type": by_type,
            "navigations": len(flow.navigations),
            "console_events": len(flow.console),
            "page_errors": len(flow.page_errors),
        }

"""Local Mock API for attack-scenario validation.

Real target is only used for SAFE_DISCOVERY.
All attack / tampering / replay tests hit this server.
"""

from __future__ import annotations

import asyncio
import json
import time
from typing import Any

from aiohttp import web


MOCK_USER = {
    "name": "TEST_USER",
    "phone": "13800000000",
    "idCard": "110101199001010000",
    "bankCard": "6222000000000000000",
    "address": "TEST_ADDRESS_ONLY",
}


def create_app() -> web.Application:
    app = web.Application()
    app["tokens"] = {"valid-token-mock": {"uses": 0, "max_uses": 1}}
    app["request_log"] = []
    app.router.add_get("/api/page", handle_page)
    app.router.add_get("/api/config", handle_config)
    app.router.add_get("/api/user", handle_user)
    app.router.add_get("/api/health", handle_health)
    app.router.add_get("/api/rate_limited", handle_rate_limited)
    app.router.add_get("/api/forbidden", handle_forbidden)
    app.router.add_get("/api/auth", handle_auth)
    app.router.add_post("/api/apply", handle_apply)
    app.router.add_post("/api/submit", handle_submit)
    app.router.add_route("*", "/{tail:.*}", handle_fallback)
    app.middlewares.append(log_middleware)
    return app


@web.middleware
async def log_middleware(request: web.Request, handler):
    started = time.time()
    try:
        resp = await handler(request)
    except web.HTTPException as exc:
        request.app["request_log"].append(
            {
                "method": request.method,
                "path": request.path,
                "status": exc.status,
                "duration_ms": round((time.time() - started) * 1000, 2),
            }
        )
        raise
    request.app["request_log"].append(
        {
            "method": request.method,
            "path": request.path,
            "status": resp.status,
            "duration_ms": round((time.time() - started) * 1000, 2),
        }
    )
    return resp


async def handle_health(_: web.Request) -> web.Response:
    return web.json_response({"ok": True, "service": "anti_bot_tester_mock"})


async def handle_page(_: web.Request) -> web.Response:
    html = """<!DOCTYPE html><html><body>
    <h1>Mock Landing</h1>
    <p>TEST_USER mock page — no real loan apply.</p>
    <script>console.log('mock page loaded');</script>
    </body></html>"""
    return web.Response(text=html, content_type="text/html")


async def handle_config(_: web.Request) -> web.Response:
    return web.json_response(
        {
            "env": "mock",
            "features": ["apply_mock", "auth_mock"],
            "apiKey": "MOCK_API_KEY_DO_NOT_USE_REAL",
        }
    )


async def handle_user(_: web.Request) -> web.Response:
    return web.json_response(MOCK_USER)


async def handle_rate_limited(_: web.Request) -> web.Response:
    return web.json_response({"error": "too many requests"}, status=429)


async def handle_forbidden(_: web.Request) -> web.Response:
    return web.json_response({"error": "forbidden by risk control"}, status=403)


async def handle_auth(request: web.Request) -> web.Response:
    auth = request.headers.get("Authorization", "")
    token = request.headers.get("X-Access-Token", "")
    if auth.startswith("Bearer valid") or token == "valid-token-mock":
        return web.json_response({"authorized": True})
    return web.json_response({"authorized": False}, status=401)


async def handle_apply(request: web.Request) -> web.Response:
    """Mock apply — accepts any JSON, never talks to real loan systems."""
    try:
        body: Any = await request.json()
    except Exception:
        body = {}
    # Detect obvious tampering markers for scenario tests
    if isinstance(body, dict) and body.get("__tamper__") is True:
        return web.json_response({"accepted": False, "reason": "tamper_detected"}, status=400)
    return web.json_response(
        {
            "accepted": True,
            "mock": True,
            "applicationId": "MOCK-APP-0001",
            "echo": {k: body.get(k) for k in ("name", "phone") if isinstance(body, dict)},
        }
    )


async def handle_submit(request: web.Request) -> web.Response:
    token = request.headers.get("X-Access-Token", "")
    tokens = request.app["tokens"]
    if token not in tokens:
        return web.json_response({"ok": False, "reason": "invalid_token"}, status=401)
    entry = tokens[token]
    entry["uses"] += 1
    if entry["uses"] > entry["max_uses"]:
        return web.json_response({"ok": False, "reason": "token_replay"}, status=403)
    return web.json_response({"ok": True, "mock": True, "uses": entry["uses"]})


async def handle_fallback(request: web.Request) -> web.Response:
    return web.json_response(
        {"error": "not_found", "path": request.path, "mock": True},
        status=404,
    )


class MockServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 8765) -> None:
        self.host = host
        self.port = port
        self._runner: web.AppRunner | None = None
        self.app = create_app()

    @property
    def base_url(self) -> str:
        return f"http://{self.host}:{self.port}"

    async def start(self) -> str:
        self._runner = web.AppRunner(self.app)
        await self._runner.setup()
        site = web.TCPSite(self._runner, self.host, self.port)
        await site.start()
        return self.base_url

    async def stop(self) -> None:
        if self._runner:
            await self._runner.cleanup()
            self._runner = None


async def _main() -> None:
    server = MockServer()
    url = await server.start()
    print(f"Mock server listening on {url}")
    try:
        while True:
            await asyncio.sleep(3600)
    except (KeyboardInterrupt, asyncio.CancelledError):
        pass
    finally:
        await server.stop()


if __name__ == "__main__":
    asyncio.run(_main())

"""Simple session / cookie jar manager for mock scenarios."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any
from uuid import uuid4


@dataclass
class SessionState:
    session_id: str
    cookies: dict[str, str] = field(default_factory=dict)
    headers: dict[str, str] = field(default_factory=dict)
    meta: dict[str, Any] = field(default_factory=dict)


class SessionManager:
    def __init__(self) -> None:
        self._sessions: dict[str, SessionState] = {}

    def create(self, *, headers: dict[str, str] | None = None) -> SessionState:
        sid = str(uuid4())
        state = SessionState(
            session_id=sid,
            headers=dict(headers or {}),
            meta={"created_for": "mock"},
        )
        state.cookies["MOCK_SESSION"] = sid
        self._sessions[sid] = state
        return state

    def get(self, session_id: str) -> SessionState | None:
        return self._sessions.get(session_id)

    def as_headers(self, session: SessionState) -> dict[str, str]:
        headers = dict(session.headers)
        if session.cookies:
            headers["Cookie"] = "; ".join(f"{k}={v}" for k, v in session.cookies.items())
        headers.setdefault("X-Session-Id", session.session_id)
        return headers

    def drop(self, session_id: str) -> None:
        self._sessions.pop(session_id, None)

    def clear(self) -> None:
        self._sessions.clear()

"""Sensitive field detection — never log raw matches."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Iterable


@dataclass
class Finding:
    category: str
    location: str
    matched_preview: str  # already masked
    pattern_name: str


@dataclass
class DetectionResult:
    findings: list[Finding] = field(default_factory=list)

    @property
    def count(self) -> int:
        return len(self.findings)

    def by_category(self) -> dict[str, int]:
        out: dict[str, int] = {}
        for f in self.findings:
            out[f.category] = out.get(f.category, 0) + 1
        return out


# Patterns intentionally match mock AND realistic shapes for detection tests.
_PATTERNS: list[tuple[str, re.Pattern[str]]] = [
    ("phone", re.compile(r"(?<!\d)1[3-9]\d{9}(?!\d)")),
    ("id_card", re.compile(r"(?<!\d)[1-9]\d{5}(?:19|20)\d{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[12]\d|3[01])\d{3}[\dXx](?!\d)")),
    ("bank_card", re.compile(r"(?<!\d)(?:62|60|4|5)\d{14,18}(?!\d)")),
    ("authorization", re.compile(r"(?i)(authorization\s*[:=]\s*Bearer\s+)([A-Za-z0-9\-._~+/]+=*)")),
    ("bearer_token", re.compile(r"(?i)(Bearer\s+)([A-Za-z0-9\-._~+/]{8,}=*)")),
    ("access_token", re.compile(r"(?i)(access[_-]?token\s*[:=]\s*)([A-Za-z0-9\-._~+/]{8,})")),
    ("refresh_token", re.compile(r"(?i)(refresh[_-]?token\s*[:=]\s*)([A-Za-z0-9\-._~+/]{8,})")),
    ("api_key", re.compile(r"(?i)(api[_-]?key\s*[:=]\s*)([A-Za-z0-9\-._]{8,})")),
    ("secret", re.compile(r"(?i)(secret\s*[:=]\s*)([A-Za-z0-9\-._]{8,})")),
    ("session_id", re.compile(r"(?i)(session[_-]?id\s*[:=]\s*)([A-Za-z0-9\-._]{8,})")),
    ("cookie_header", re.compile(r"(?i)(cookie\s*[:=]\s*)([^\n\r]{8,})")),
]


class SensitiveDetector:
    """Scan text for sensitive patterns and return masked findings only."""

    def __init__(self) -> None:
        from security.data_masker import DataMasker

        self.masker = DataMasker()

    def scan_text(self, text: str, *, location: str) -> DetectionResult:
        if not text:
            return DetectionResult()
        findings: list[Finding] = []
        for name, pattern in _PATTERNS:
            for match in pattern.finditer(text):
                raw = match.group(0)
                preview = self.masker.mask_value(raw, category=name)
                findings.append(
                    Finding(
                        category=self._category_for(name),
                        location=location,
                        matched_preview=preview,
                        pattern_name=name,
                    )
                )
        # Name / address heuristics (mock labels)
        if re.search(r"\bTEST_USER\b|\b[\u4e00-\u9fff]{2,4}\b", text):
            if "TEST_USER" in text or re.search(r'"name"\s*:\s*"[^"]+"', text):
                findings.append(
                    Finding(
                        category="name",
                        location=location,
                        matched_preview=self.masker.mask_name("TEST_USER"),
                        pattern_name="name_hint",
                    )
                )
        if "TEST_ADDRESS" in text or re.search(r'(?i)"address"\s*:\s*"[^"]+"', text):
            findings.append(
                Finding(
                    category="address",
                    location=location,
                    matched_preview="***ADDRESS***",
                    pattern_name="address_hint",
                )
            )
        return DetectionResult(findings=findings)

    def scan_mapping(
        self, data: dict[str, str] | None, *, location_prefix: str
    ) -> DetectionResult:
        result = DetectionResult()
        if not data:
            return result
        for k, v in data.items():
            key_l = k.lower()
            # Header names that are sensitive by nature
            if key_l in {"authorization", "cookie", "x-api-key", "x-access-token"}:
                preview = self.masker.mask_header(k, v)
                result.findings.append(
                    Finding(
                        category="token" if "auth" in key_l or "token" in key_l else "cookie",
                        location=f"{location_prefix}.{k}",
                        matched_preview=preview,
                        pattern_name=f"header:{k}",
                    )
                )
            sub = self.scan_text(f"{k}={v}", location=f"{location_prefix}.{k}")
            result.findings.extend(sub.findings)
        return result

    def scan_parts(
        self,
        *,
        url: str = "",
        request_headers: dict[str, str] | None = None,
        request_body: str = "",
        response_headers: dict[str, str] | None = None,
        response_body: str = "",
        html: str = "",
        console: str = "",
        error: str = "",
    ) -> DetectionResult:
        parts: list[DetectionResult] = [
            self.scan_text(url, location="url"),
            self.scan_mapping(request_headers, location_prefix="request_header"),
            self.scan_text(request_body, location="request_body"),
            self.scan_mapping(response_headers, location_prefix="response_header"),
            self.scan_text(response_body, location="response_body"),
            self.scan_text(html, location="html"),
            self.scan_text(console, location="console"),
            self.scan_text(error, location="error"),
        ]
        merged = DetectionResult()
        for p in parts:
            merged.findings.extend(p.findings)
        return merged

    @staticmethod
    def _category_for(pattern_name: str) -> str:
        mapping = {
            "phone": "phone",
            "id_card": "id_card",
            "bank_card": "bank_card",
            "authorization": "authorization",
            "bearer_token": "token",
            "access_token": "access_token",
            "refresh_token": "refresh_token",
            "api_key": "api_key",
            "secret": "secret",
            "session_id": "session_id",
            "cookie_header": "cookie",
        }
        return mapping.get(pattern_name, pattern_name)

"""Mask sensitive values before logging or reporting."""

from __future__ import annotations

import re


class DataMasker:
    PHONE_RE = re.compile(r"(?<!\d)(1[3-9]\d)\d{4}(\d{4})(?!\d)")
    ID_RE = re.compile(
        r"(?<!\d)([1-9]\d{2})\d{11}(\d{2}[\dXx])(?!\d)"
    )
    BANK_RE = re.compile(r"(?<!\d)(\d{4})\d{8,14}(\d{4})(?!\d)")

    def mask_phone(self, value: str) -> str:
        return self.PHONE_RE.sub(r"\1****\2", value)

    def mask_id_card(self, value: str) -> str:
        # 110***********0000 style for 18-digit
        def repl(m: re.Match[str]) -> str:
            s = m.group(0)
            if len(s) >= 8:
                return s[:3] + ("*" * (len(s) - 7)) + s[-4:]
            return "***"

        return self.ID_RE.sub(repl, value)

    def mask_bank_card(self, value: str) -> str:
        def repl(m: re.Match[str]) -> str:
            s = m.group(0)
            if len(s) >= 8:
                return s[:4] + ("*" * (len(s) - 8)) + s[-4:]
            return "****"

        return self.BANK_RE.sub(repl, value)

    def mask_authorization(self, value: str) -> str:
        if re.search(r"(?i)bearer\s+\S+", value):
            return re.sub(r"(?i)(Bearer\s+)\S+", r"\1********", value)
        if len(value) > 8:
            return value[:4] + "********"
        return "********"

    def mask_token(self, value: str) -> str:
        return "********"

    def mask_name(self, value: str) -> str:
        if not value:
            return "***"
        if len(value) == 1:
            return "*"
        return value[0] + ("*" * (len(value) - 1))

    def mask_header(self, name: str, value: str) -> str:
        key = name.lower()
        if key == "authorization":
            return self.mask_authorization(value)
        if "token" in key or key in {"x-api-key", "x-access-token"}:
            return f"{name}: ********"
        if key == "cookie":
            return "Cookie: ********"
        return f"{name}: {self.mask_text(value)}"

    def mask_value(self, value: str, *, category: str = "") -> str:
        cat = category.lower()
        if cat in {"phone"}:
            return self.mask_phone(value)
        if cat in {"id_card"}:
            return self.mask_id_card(value)
        if cat in {"bank_card"}:
            return self.mask_bank_card(value)
        if cat in {"authorization", "bearer_token"}:
            return self.mask_authorization(value)
        if cat in {
            "token",
            "access_token",
            "refresh_token",
            "api_key",
            "secret",
            "session_id",
            "cookie",
            "cookie_header",
        }:
            return self.mask_token(value)
        if cat == "name":
            return self.mask_name(value)
        return self.mask_text(value)

    def mask_text(self, text: str) -> str:
        if not text:
            return text
        out = self.mask_phone(text)
        out = self.mask_id_card(out)
        out = self.mask_bank_card(out)
        out = re.sub(r"(?i)(Bearer\s+)\S+", r"\1********", out)
        out = re.sub(
            r"(?i)((?:access|refresh)[_-]?token\s*[:=]\s*)\S+",
            r"\1********",
            out,
        )
        out = re.sub(r"(?i)(api[_-]?key\s*[:=]\s*)\S+", r"\1********", out)
        out = re.sub(r"(?i)(secret\s*[:=]\s*)\S+", r"\1********", out)
        return out

"""Token / replay related checks against mock auth responses."""

from __future__ import annotations

from dataclasses import dataclass

from crawler.http_client import HttpResponse


@dataclass
class TokenCheckResult:
    present: bool
    accepted: bool
    replay_blocked: bool
    detail: str


class TokenChecker:
    """Evaluate whether mock endpoints enforce token / anti-replay."""

    def evaluate_auth_response(self, resp: HttpResponse) -> TokenCheckResult:
        if resp.status == 401:
            return TokenCheckResult(
                present=True, accepted=False, replay_blocked=False, detail="unauthorized"
            )
        if resp.status == 403 and "replay" in (resp.body or "").lower():
            return TokenCheckResult(
                present=True, accepted=False, replay_blocked=True, detail="replay_blocked"
            )
        if 200 <= resp.status < 300:
            return TokenCheckResult(
                present=True, accepted=True, replay_blocked=False, detail="accepted"
            )
        return TokenCheckResult(
            present=False, accepted=False, replay_blocked=False, detail=f"status={resp.status}"
        )

"""Attack scenario base interface + shared helpers."""

from __future__ import annotations

import abc
import asyncio
import time
from dataclasses import dataclass, field
from typing import Any

from app.models import AppConfig
from crawler.http_client import HttpClient, HttpResponse
from monitor.metrics import MetricsCollector


@dataclass
class ScenarioResult:
    name: str
    description: str
    started_at: float
    finished_at: float
    responses: list[HttpResponse] = field(default_factory=list)
    extra: dict[str, Any] = field(default_factory=dict)

    def statistics(self) -> dict[str, Any]:
        total = len(self.responses)
        by_status: dict[int, int] = {}
        for r in self.responses:
            by_status[r.status] = by_status.get(r.status, 0) + 1
        return {
            "name": self.name,
            "description": self.description,
            "total_requests": total,
            "by_status": by_status,
            "duration_seconds": round(self.finished_at - self.started_at, 3),
            "extra": self.extra,
        }


class AttackScenario(abc.ABC):
    name: str = "base"
    description: str = ""

    def __init__(self, config: AppConfig, metrics: MetricsCollector | None = None) -> None:
        self.config = config
        self.metrics = metrics or MetricsCollector()
        self._stop = asyncio.Event()
        self._result: ScenarioResult | None = None

    def stop(self) -> None:
        self._stop.set()

    def statistics(self) -> dict[str, Any]:
        if self._result:
            return self._result.statistics()
        return {"name": self.name, "total_requests": 0}

    @abc.abstractmethod
    async def run(self) -> ScenarioResult:
        raise NotImplementedError

    def _should_stop(self) -> bool:
        return self._stop.is_set()

    async def _record(self, resp: HttpResponse) -> None:
        self.metrics.record_response(resp)
        await asyncio.sleep(0)  # yield

"""Statistics helpers."""

from __future__ import annotations

from typing import Any


def merge_status_counts(*dicts: dict[int, int]) -> dict[int, int]:
    out: dict[int, int] = {}
    for d in dicts:
        for k, v in d.items():
            out[k] = out.get(k, 0) + v
    return out


def format_stats(stats: dict[str, Any]) -> str:
    lines = [f"{k}: {v}" for k, v in stats.items()]
    return "\n".join(lines)

