"""Environment mode hard gates for observation vs attack operations."""

from __future__ import annotations

import os
from enum import Enum

from app.models import AppConfig


class EnvironmentMode(str, Enum):
    REAL_OBSERVATION = "REAL_OBSERVATION"
    MOCK_ATTACK = "MOCK_ATTACK"
    STAGING_ATTACK = "STAGING_ATTACK"


ATTACK_OPERATIONS = frozenset(
    {
        "replay",
        "tamper",
        "hijack",
        "load-test",
        "concurrent-attack",
        "parameter_tampering",
        "request_hijack",
    }
)


class EnvironmentGuardError(Exception):
    """Raised when an operation is blocked by environment policy."""


class EnvironmentGuard:
    """Split REAL observation from MOCK/STAGING attack surfaces.

    REAL_OBSERVATION: browse + user-driven observe + mask + analyze only.
    MOCK_ATTACK: hijack/replay/tamper/load against local mock.
    STAGING_ATTACK: only when AUTHORIZED_STAGING=true (explicit).
    Production real domains must never enter ATTACK mode.
    """

    def __init__(self, config: AppConfig) -> None:
        self.config = config
        raw = getattr(config, "environment_mode", None) or "REAL_OBSERVATION"
        try:
            self.mode = EnvironmentMode(raw)
        except ValueError as exc:
            raise EnvironmentGuardError(
                f"Invalid environment_mode={raw!r}. "
                f"Use REAL_OBSERVATION | MOCK_ATTACK | STAGING_ATTACK"
            ) from exc

    @property
    def authorized_staging(self) -> bool:
        cfg_flag = bool(getattr(self.config, "authorized_staging", False))
        env_flag = os.environ.get("AUTHORIZED_STAGING", "").lower() in {
            "1",
            "true",
            "yes",
        }
        return cfg_flag or env_flag

    def assert_observation_only(self) -> None:
        if self.mode != EnvironmentMode.REAL_OBSERVATION:
            # Observation CLI can still run under REAL; if user set MOCK that's ok for analyze of saved files
            pass

    def assert_attack_allowed(self, operation: str, *, against_real: bool) -> None:
        op = operation.lower().strip()
        if against_real:
            raise EnvironmentGuardError(
                "BLOCKED:\n"
                "Attack operations are disabled against real targets.\n"
                f"Attempted operation: {op}"
            )
        if self.mode == EnvironmentMode.REAL_OBSERVATION:
            raise EnvironmentGuardError(
                "BLOCKED:\n"
                "Attack operations are disabled in REAL_OBSERVATION mode.\n"
                f"Attempted operation: {op}\n"
                "Use MOCK_ATTACK (local mock) for hijack/replay/tamper tests."
            )
        if self.mode == EnvironmentMode.STAGING_ATTACK and not self.authorized_staging:
            raise EnvironmentGuardError(
                "BLOCKED:\n"
                "STAGING_ATTACK requires AUTHORIZED_STAGING=true "
                "(config or environment)."
            )
        if self.mode == EnvironmentMode.MOCK_ATTACK:
            return
        if self.mode == EnvironmentMode.STAGING_ATTACK and self.authorized_staging:
            return
        raise EnvironmentGuardError(f"BLOCKED: operation {op} not permitted")

    def is_real_observation(self) -> bool:
        return self.mode == EnvironmentMode.REAL_OBSERVATION

    def banner(self) -> str:
        return (
            f"environment_mode : {self.mode.value}\n"
            f"authorized_staging: {self.authorized_staging}\n"
            "real-target attacks : DISABLED"
        )

