"""Request fingerprinting — structure only, never raw PII."""

from __future__ import annotations

import hashlib
import json
import re
from typing import Any
from urllib.parse import urlsplit


class RequestFingerprint:
    """Compute a stable fingerprint from method + path + field names + security headers.

    Values are never included in the fingerprint material.
    """

    SENSITIVE_HEADER_KEYS = frozenset(
        {
            "authorization",
            "cookie",
            "set-cookie",
            "x-api-key",
            "x-access-token",
            "x-auth-token",
        }
    )

    def path_template(self, url: str) -> str:
        parts = urlsplit(url)
        path = parts.path or "/"
        # Replace long numeric segments
        path = re.sub(r"/\d{4,}", "/{id}", path)
        path = re.sub(r"/[0-9a-f]{8,}", "/{hex}", path, flags=re.I)
        return f"{parts.scheme}://{parts.netloc}{path}"

    def field_names_from_body(self, body: str | None, content_type: str | None) -> list[str]:
        if not body:
            return []
        ct = (content_type or "").lower()
        names: list[str] = []
        if "json" in ct or body.strip().startswith("{") or body.strip().startswith("["):
            try:
                data = json.loads(body)
                names = self._collect_keys(data)
            except json.JSONDecodeError:
                names = re.findall(r'"([A-Za-z_][A-Za-z0-9_]*)"\s*:', body)
        elif "x-www-form-urlencoded" in ct:
            from urllib.parse import parse_qsl

            names = [k for k, _ in parse_qsl(body, keep_blank_values=True)]
        return sorted(set(names))

    def _collect_keys(self, obj: Any, prefix: str = "") -> list[str]:
        keys: list[str] = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                path = f"{prefix}.{k}" if prefix else str(k)
                keys.append(path)
                keys.extend(self._collect_keys(v, path))
        elif isinstance(obj, list) and obj:
            keys.extend(self._collect_keys(obj[0], prefix + "[]"))
        return keys

    def header_names(self, headers: dict[str, str] | None) -> list[str]:
        if not headers:
            return []
        return sorted(k.lower() for k in headers.keys())

    def compute(
        self,
        *,
        method: str,
        url: str,
        content_type: str | None = None,
        header_names: list[str] | None = None,
        field_names: list[str] | None = None,
    ) -> str:
        material = {
            "method": method.upper(),
            "path": self.path_template(url),
            "content_type": (content_type or "").split(";")[0].strip().lower(),
            "headers": sorted(h.lower() for h in (header_names or [])),
            "fields": sorted(field_names or []),
        }
        blob = json.dumps(material, sort_keys=True, ensure_ascii=False)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()[:32]

"""Static replay-risk analysis — never replays against real servers."""

from __future__ import annotations

import re
from dataclasses import asdict, dataclass
from typing import Any


@dataclass
class ReplayRiskAnalysis:
    nonce: bool = False
    timestamp: bool = False
    request_signature: bool = False
    idempotency_key: bool = False
    session_binding: str = "unknown"
    device_binding: str = "unknown"
    replay_risk: str = "HIGH"

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


_NONCE_KEYS = re.compile(
    r"(?i)\b(nonce|once|request[_-]?id|req[_-]?id|uuid|trace[_-]?id)\b"
)
_TS_KEYS = re.compile(r"(?i)\b(timestamp|ts|time[_-]?stamp|expire[sd]?|exp|iat)\b")
_SIG_KEYS = re.compile(
    r"(?i)\b(sign|signature|sig|hmac|hash|checksum|x-sign|x-signature)\b"
)
_IDEM_KEYS = re.compile(r"(?i)\b(idempotency[_-]?key|idempotent|unique[_-]?key)\b")
_SESSION_KEYS = re.compile(r"(?i)\b(session|sid|jsessionid|x-session)\b")
_DEVICE_KEYS = re.compile(
    r"(?i)\b(device[_-]?id|deviceid|imei|android[_-]?id|idfa|oaid|equipment)\b"
)


class ReplayDetector:
    """Infer replay protection from request structure only (static)."""

    def analyze(
        self,
        *,
        field_names: list[str] | None = None,
        header_names: list[str] | None = None,
        url: str = "",
        has_https: bool = True,
    ) -> ReplayRiskAnalysis:
        names = " ".join((field_names or []) + (header_names or []) + [url])
        nonce = bool(_NONCE_KEYS.search(names))
        timestamp = bool(_TS_KEYS.search(names))
        signature = bool(_SIG_KEYS.search(names))
        idem = bool(_IDEM_KEYS.search(names))
        session = "likely" if _SESSION_KEYS.search(names) else "unknown"
        device = "likely" if _DEVICE_KEYS.search(names) else "unknown"

        score = 0
        if nonce:
            score += 2
        if timestamp:
            score += 2
        if signature:
            score += 3
        if idem:
            score += 2
        if session == "likely":
            score += 1
        if device == "likely":
            score += 1
        if not has_https:
            score = 0

        if score >= 7:
            risk = "LOW"
        elif score >= 4:
            risk = "MEDIUM"
        elif score >= 2:
            risk = "HIGH"
        else:
            risk = "CRITICAL" if has_https else "CRITICAL"

        # Without nonce+timestamp+signature, treat as HIGH minimum when HTTPS body has PII
        if not (nonce and timestamp and signature):
            if risk == "LOW":
                risk = "MEDIUM"
            if not signature and not nonce:
                risk = "HIGH" if risk != "CRITICAL" else risk

        return ReplayRiskAnalysis(
            nonce=nonce,
            timestamp=timestamp,
            request_signature=signature,
            idempotency_key=idem,
            session_binding=session,
            device_binding=device,
            replay_risk=risk,
        )

