                out.append(phone)
        return sorted(set(out))

    def mask_phone(self, value: str) -> str:
        def repl(m: re.Match[str]) -> str:
            phone = m.group(1)
            if self.reveal_phone and (
                not self.allowed_phones or phone in self.allowed_phones
            ):
                return phone
            return phone[:3] + "****" + phone[7:]

        return self.PHONE_RE.sub(repl, value)

    def mask_id_card(self, value: str) -> str:
        def repl(m: re.Match[str]) -> str:
            s = m.group(0)
            if len(s) >= 10:
                return s[:6] + ("*" * (len(s) - 10)) + s[-4:]
            return "[ID_REDACTED]"

        return self.ID_FULL_RE.sub(repl, value)

    def mask_bank_card(self, value: str) -> str:
        def repl(m: re.Match[str]) -> str:
            s = m.group(0)
            if len(s) >= 8:
                return s[:4] + ("*" * (len(s) - 8)) + s[-4:]
            return "[BANK_REDACTED]"

        return self.BANK_RE.sub(repl, value)

    def mask_email(self, value: str) -> str:
        def repl(m: re.Match[str]) -> str:
            s = m.group(0)
            local, _, domain = s.partition("@")
            keep = local[:1] if local else "*"
            return f"{keep}***@{domain}"

        return self.EMAIL_RE.sub(repl, value)

    def mask_authorization(self, value: str) -> str:
        if re.search(r"(?i)bearer\s+\S+", value):
            return re.sub(r"(?i)Bearer\s+\S+", "Bearer [TOKEN_REDACTED]", value)
        return "[TOKEN_REDACTED]"

    def mask_token(self, value: str) -> str:
        return "[TOKEN_REDACTED]"

    def mask_cookie(self, value: str) -> str:
        return "[COOKIE_REDACTED]"

    def mask_name(self, value: str) -> str:
        if not value:
            return "[NAME_REDACTED]"
        if len(value) == 1:
            return "*"
        return value[0] + ("*" * (len(value) - 1))

    def mask_url(self, url: str) -> str:
        if not url:
            return "[MASKED]"
        from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

        parts = urlsplit(url)
        if not parts.query:
            return self.mask_text(url)
        masked_q = []
        for k, v in parse_qsl(parts.query, keep_blank_values=True):
            kl = k.lower()
            if "phone" in kl or "mobile" in kl or "tel" in kl:
                masked_q.append(
                    (k, self.mask_phone(v) if self.reveal_phone else "[REDACTED]")
                )
            elif any(
                x in kl
                for x in (
                    "idcard",
                    "id_card",
                    "bank",
                    "token",
                    "auth",
                    "session",
                    "cookie",
                    "secret",
                    "name",
                )
            ):
                masked_q.append((k, "[REDACTED]")
                )
            else:
                masked_q.append((k, self.mask_text(v)))
        return urlunsplit(
            (
                parts.scheme,
                parts.netloc,
                parts.path,
                urlencode(masked_q),
                self.mask_text(parts.fragment) if parts.fragment else "",
            )
        )

    def mask_header(self, name: str, value: str) -> str:
        key = name.lower()
        if key == "authorization":
            return f"{name}: {self.mask_authorization(value)}"
        if key in {"cookie", "set-cookie"}:
            return f"{name}: {self.mask_cookie(value)}"
        if "token" in key or key in {"x-api-key", "x-access-token", "x-auth-token"}:
            return f"{name}: {self.mask_token(value)}"
        return f"{name}: {self.mask_text(value)}"

    def mask_value(self, value: str, *, category: str = "") -> str:
        cat = category.lower()
        if cat in {"phone"}:
            return self.mask_phone(value)
        if cat in {"id_card"}:
            return self.mask_id_card(value)
        if cat in {"bank_card"}:
            return self.mask_bank_card(value)
        if cat in {"email"}:
            return self.mask_email(value)
        if cat in {"authorization", "bearer_token"}:
            return self.mask_authorization(value)
        if cat in {
            "token",
            "access_token",
            "refresh_token",
            "api_key",
            "secret",
            "session_id",
        }:
            return self.mask_token(value)
        if cat in {"cookie", "cookie_header"}:
            return self.mask_cookie(value)
        if cat == "name":
            return self.mask_name(value)
        return self.mask_text(value)

    def mask_text(self, text: str) -> str:
        if not text:
            return text
        out = self.JWT_RE.sub("[TOKEN_REDACTED]", text)
        out = self.mask_phone(out)
        out = self.mask_id_card(out)
        out = self.mask_bank_card(out)
        out = self.mask_email(out)
        out = re.sub(r"(?i)(Bearer\s+)\S+", r"\1[TOKEN_REDACTED]", out)
        out = re.sub(
            r"(?i)((?:access|refresh)[_-]?token\s*[:=]\s*)\S+",
            r"\1[TOKEN_REDACTED]",
            out,
        )
        out = re.sub(r"(?i)(api[_-]?key\s*[:=]\s*)\S+", r"\1[TOKEN_REDACTED]", out)
        out = re.sub(r"(?i)(secret\s*[:=]\s*)\S+", r"\1[TOKEN_REDACTED]", out)
        out = re.sub(r"(?i)(cookie\s*[:=]\s*)[^\n\r]+", r"\1[COOKIE_REDACTED]", out)
        return out

    def redact_json_values(self, obj: object) -> object:
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                kl = str(k).lower()
                if any(
                    x in kl
                    for x in (
                        "phone",
                        "mobile",
                        "idcard",
                        "id_card",
                        "bank",
                        "token",
                        "auth",
                        "session",
                        "cookie",
                        "secret",
                        "password",
                        "name",
                        "address",
                        "email",
                    )
                ):
                    if isinstance(v, str):
                        out[k] = self.mask_value(v, category=self._guess_category(kl))
                    else:
                        out[k] = "[REDACTED]"
                else:
                    out[k] = self.redact_json_values(v)
            return out
        if isinstance(obj, list):
            return [self.redact_json_values(x) for x in obj]
        if isinstance(obj, str):
            return self.mask_text(obj)
        return obj

    @staticmethod
    def _guess_category(key_lower: str) -> str:
        if "phone" in key_lower or "mobile" in key_lower:
            return "phone"
        if "idcard" in key_lower or "id_card" in key_lower or "idno" in key_lower:
            return "id_card"
        if "bank" in key_lower or "card" in key_lower:
            return "bank_card"
        if "email" in key_lower:
            return "email"
        if "cookie" in key_lower:
            return "cookie"
        if "token" in key_lower or "auth" in key_lower:
            return "token"
        if "name" in key_lower:
            return "name"
        if "address" in key_lower or "addr" in key_lower:
            return "address"
        return ""

