"""Field / payload protection classification (not crypto breaking)."""

from __future__ import annotations

import base64
import binascii
import json
import re
from dataclasses import asdict, dataclass
from typing import Any
from urllib.parse import urlsplit


@dataclass
class TransportSecurity:
    https: bool
    tls: bool  # https implies TLS for our purposes

    def to_dict(self) -> dict[str, bool]:
        return asdict(self)


# Heuristic classifiers — Base64 ≠ encryption
_BASE64_RE = re.compile(r"^[A-Za-z0-9+/]+=*$")
_HEX_RE = re.compile(r"^[0-9a-fA-F]+$")
_JWT_RE = re.compile(r"^eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$")
_HASH_HINT = re.compile(r"(?i)^(sha|md5|hash|digest)")
_ENC_HINT = re.compile(
    r"(?i)(encrypt|cipher|aes|rsa|sm4|gcm|U2FsdGVkX1|-----BEGIN)"
)


class EncryptionDetector:
    """Distinguish transport HTTPS vs payload encoding/encryption heuristics."""

    def transport(self, url: str) -> TransportSecurity:
        https = urlsplit(url).scheme.lower() == "https"
        return TransportSecurity(https=https, tls=https)

    def classify_value(self, value: Any, *, field_name: str = "") -> str:
        """Return one of: PLAINTEXT | BASE64 | ENCODED | HASHED | ENCRYPTED | SIGNED | UNKNOWN."""
        if value is None:
            return "UNKNOWN"
        if not isinstance(value, str):
            return "PLAINTEXT"
        s = value.strip()
        if not s:
            return "UNKNOWN"
        name = field_name.lower()

        if _JWT_RE.match(s):
            return "SIGNED"
        if _ENC_HINT.search(name) or _ENC_HINT.search(s[:32]):
            if self._looks_encrypted_blob(s):
                return "ENCRYPTED"
        if _HASH_HINT.search(name):
            if len(s) in {32, 40, 64, 128} and _HEX_RE.match(s):
                return "HASHED"
        if len(s) in {32, 40, 64, 128} and _HEX_RE.match(s) and "hash" in name:
            return "HASHED"

        # OpenSSL Salted__ base64 prefix often used by CryptoJS
        if s.startswith("U2FsdGVkX1") or (self._is_b64(s) and len(s) > 40 and self._high_entropy_b64(s)):
            # Still not proof of encryption — mark ENCRYPTED only with strong hints
            if s.startswith("U2FsdGVkX1") or "encrypt" in name or "cipher" in name or "data" == name:
                if s.startswith("U2FsdGVkX1"):
                    return "ENCRYPTED"
                # generic long base64 under data/payload → ENCODED not ENCRYPTED
                return "ENCODED" if name in {"data", "payload", "content"} else "BASE64"

        if self._is_b64(s) and len(s) >= 16:
            # Try decode — if decodes to readable JSON/text with PII shape → ENCODED
            decoded = self._try_b64_decode(s)
            if decoded is not None:
                try:
                    text = decoded.decode("utf-8")
                    if text.lstrip().startswith(("{", "[")):
                        return "ENCODED"
                    if re.search(r"1[3-9]\d{9}", text):
                        return "ENCODED"  # base64 wrapping plaintext PII
                    return "BASE64"
                except UnicodeDecodeError:
                    # binary after b64 — could be encrypted OR compressed
                    if "encrypt" in name or "cipher" in name:
                        return "ENCRYPTED"
                    return "ENCODED"
            return "BASE64"

        # Cleartext sensitive patterns
        if re.fullmatch(r"1[3-9]\d{9}", s):
            return "PLAINTEXT"
        if re.fullmatch(
            r"[1-9]\d{5}(?:19|20)\d{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[12]\d|3[01])\d{3}[\dXx]",
            s,
        ):
            return "PLAINTEXT"
        if re.fullmatch(r"\d{16,19}", s):
            return "PLAINTEXT"
        return "PLAINTEXT" if s.isprintable() and len(s) < 200 else "UNKNOWN"

    def analyze_body_fields(
        self, body: str | None, field_names: list[str] | None = None
    ) -> dict[str, dict[str, Any]]:
        """Per-field protection status without storing raw values."""
        result: dict[str, dict[str, Any]] = {}
        if not body:
            return result
        obj = None
        try:
            obj = json.loads(body)
        except json.JSONDecodeError:
            # whole-body classification
            ptype = self.classify_value(body, field_name="body")
            result["_payload"] = {
                "detected": True,
                "protected": ptype in {"ENCRYPTED", "HASHED", "SIGNED"},
                "protection_type": ptype,
            }
            return result

        def walk(node: Any, prefix: str = "") -> None:
            if isinstance(node, dict):
                for k, v in node.items():
                    path = f"{prefix}.{k}" if prefix else str(k)
                    if isinstance(v, (dict, list)):
                        walk(v, path)
                    else:
                        leaf = str(k)
                        ptype = self.classify_value(v, field_name=leaf)
                        # Only record likely sensitive leaves or encrypted wrappers
                        from security.sensitive_detector import SensitiveDetector

                        cat = SensitiveDetector().classify_field_name(leaf)
                        if cat or ptype in {"ENCRYPTED", "HASHED", "SIGNED", "ENCODED"}:
                            key = (cat or leaf).upper() if cat else leaf
                            # normalize common cats
                            if cat:
                                key = cat.upper()
                            result[key] = {
                                "detected": True,
                                "protected": ptype
                                in {"ENCRYPTED", "HASHED", "SIGNED"},
                                "protection_type": ptype,
                                "field_name": leaf,
                            }
            elif isinstance(node, list) and node:
                walk(node[0], prefix + "[]")

        walk(obj)
        return result

    def has_plaintext_sensitive(self, field_status: dict[str, dict[str, Any]]) -> bool:
        for st in field_status.values():
            if st.get("protection_type") == "PLAINTEXT" and st.get("detected"):
                # only for known sensitive categories
                return True
        return False

    @staticmethod
    def _is_b64(s: str) -> bool:
        if len(s) < 8 or len(s) % 4 != 0:
            return False
        if not _BASE64_RE.match(s):
            return False
        return True

    @staticmethod
    def _try_b64_decode(s: str) -> bytes | None:
        try:
            return base64.b64decode(s, validate=True)
        except (binascii.Error, ValueError):
            try:
                return base64.urlsafe_b64decode(s + "===")
            except (binascii.Error, ValueError):
                return None

    @staticmethod
    def _high_entropy_b64(s: str) -> bool:
        # crude: many distinct chars
        return len(set(s)) > min(40, len(s) // 2)

    @staticmethod
    def _looks_encrypted_blob(s: str) -> bool:
        return len(s) >= 24 and (s.startswith("U2FsdGVkX1") or EncryptionDetector._is_b64(s))

"""Static replay risk analysis (never replays real traffic)."""

from __future__ import annotations

from dataclasses import asdict, dataclass
from typing import Any

from security.signature_detector import SignatureDetector, SignatureFeatures


@dataclass
class ReplayProtectionReport:
    nonce: bool = False
    timestamp: bool = False
    signature: bool = False
    idempotency_key: bool = False
    session_binding: bool = False
    device_binding: bool = False
    risk: str = "HIGH"

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


class ReplayAnalyzer:
    def __init__(self) -> None:
        self.sig = SignatureDetector()

    def analyze(
        self,
        *,
        field_names: list[str] | None = None,
        header_names: list[str] | None = None,
        url: str = "",
        session_binding: bool = False,
        device_binding: bool = False,
        has_https: bool = True,
    ) -> ReplayProtectionReport:
        feats = self.sig.detect(
            field_names=field_names, header_names=header_names, url=url
        )
        score = 0
        if feats.nonce:
            score += 2
        if feats.timestamp:
            score += 2
        if feats.signature:
            score += 3
        if feats.idempotency_key:
            score += 2
        if session_binding:
            score += 1
        if device_binding:
            score += 1
        if not has_https:
            score = 0

        if score >= 8:
            risk = "LOW"
        elif score >= 5:
            risk = "MEDIUM"
        elif score >= 2:
            risk = "HIGH"
        else:
            risk = "CRITICAL"

        if not (feats.nonce and feats.timestamp and feats.signature) and risk == "LOW":
            risk = "MEDIUM"

        return ReplayProtectionReport(
            nonce=feats.nonce,
            timestamp=feats.timestamp,
            signature=feats.signature,
            idempotency_key=feats.idempotency_key,
            session_binding=session_binding,
            device_binding=device_binding,
            risk=risk,
        )

"""Configurable risk scoring for application security events."""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml


DEFAULT_RULES: dict[str, Any] = {
    "bonuses": {
        "https": 20,
        "payload_encryption": 20,
        "signature": 15,
        "timestamp": 10,
        "nonce": 10,
        "replay_protection": 15,
        "device_binding": 10,
    },
    "penalties": {
        "plaintext_sensitive": -30,
        "pii_in_url": -30,
        "no_signature": -15,
        "no_timestamp": -10,
        "no_nonce": -10,
        "no_replay_protection": -30,
        "no_device_binding": -15,
    },
    "levels": {
        "LOW": [90, 100],
        "MEDIUM": [70, 89],
        "HIGH": [40, 69],
        "CRITICAL": [0, 39],
    },
}


@dataclass
class RiskResult:
    score: int
    level: str
    breakdown: dict[str, int] = field(default_factory=dict)
    alerts: list[dict[str, str]] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "score": self.score,
            "level": self.level,
            "breakdown": self.breakdown,
            "alerts": self.alerts,
        }


class RiskEngine:
    def __init__(self, rules: dict[str, Any] | None = None) -> None:
        self.rules = rules or DEFAULT_RULES

    @classmethod
    def from_file(cls, path: str | Path) -> "RiskEngine":
        p = Path(path)
        if not p.exists():
            return cls()
        data = yaml.safe_load(p.read_text(encoding="utf-8")) or {}
        merged = {**DEFAULT_RULES, **data}
        for k in ("bonuses", "penalties", "levels"):
            if k in data and isinstance(data[k], dict):
                merged[k] = {**DEFAULT_RULES[k], **data[k]}
        return cls(merged)

    def score(
        self,
        *,
        https: bool,
        payload_encrypted: bool,
        signature: bool,
        timestamp: bool,
        nonce: bool,
        replay_ok: bool,
        device_binding: bool,
        plaintext_sensitive: bool,
        pii_in_url: bool,
    ) -> RiskResult:
        b = self.rules["bonuses"]
        p = self.rules["penalties"]
        breakdown: dict[str, int] = {}
        total = 0

        def add(key: str, points: int) -> None:
            nonlocal total
            breakdown[key] = points
            total += points

        if https:
            add("https", int(b["https"]))
        if payload_encrypted:
            add("payload_encryption", int(b["payload_encryption"]))
        if signature:
            add("signature", int(b["signature"]))
        else:
            add("no_signature", int(p["no_signature"]))
        if timestamp:
            add("timestamp", int(b["timestamp"]))
        else:
            add("no_timestamp", int(p["no_timestamp"]))
        if nonce:
            add("nonce", int(b["nonce"]))
        else:
            add("no_nonce", int(p["no_nonce"]))
        if replay_ok:
            add("replay_protection", int(b["replay_protection"]))
        else:
            add("no_replay_protection", int(p["no_replay_protection"]))
        if device_binding:
            add("device_binding", int(b["device_binding"]))
        else:
            add("no_device_binding", int(p["no_device_binding"]))
        if plaintext_sensitive:
            add("plaintext_sensitive", int(p["plaintext_sensitive"]))
        if pii_in_url:
            add("pii_in_url", int(p["pii_in_url"]))

        total = max(0, min(100, total))
        level = self._level(total)
        alerts = self._alerts(
            https=https,
            plaintext_sensitive=plaintext_sensitive,
            pii_in_url=pii_in_url,
            signature=signature,
            replay_ok=replay_ok,
            level=level,
        )
        return RiskResult(score=total, level=level, breakdown=breakdown, alerts=alerts)

    def _level(self, score: int) -> str:
        levels = self.rules["levels"]
        for name in ("LOW", "MEDIUM", "HIGH", "CRITICAL"):
            lo, hi = levels[name]
            if lo <= score <= hi:
                return name
        return "CRITICAL"

    @staticmethod
    def _alerts(
        *,
        https: bool,
        plaintext_sensitive: bool,
        pii_in_url: bool,
        signature: bool,
        replay_ok: bool,
        level: str,
    ) -> list[dict[str, str]]:
        alerts: list[dict[str, str]] = []
        if plaintext_sensitive:
            alerts.append(
                {
                    "type": "SENSITIVE_DATA_EXPOSURE",
                    "severity": "HIGH",
                }
            )
        if pii_in_url:
            alerts.append(
                {
                    "type": "SENSITIVE_DATA_IN_URL",
                    "severity": "CRITICAL",
                }
            )
        if not replay_ok:
            alerts.append({"type": "REPLAY_RISK", "severity": "HIGH"})
        if not signature:
            alerts.append(
                {"type": "REQUEST_INTEGRITY_RISK", "severity": "HIGH"}
            )
        if not https:
