"""Timezone helpers — display Asia/Shanghai (UTC+8)."""

from __future__ import annotations

from datetime import datetime, timezone
from zoneinfo import ZoneInfo

TZ_SHANGHAI = ZoneInfo("Asia/Shanghai")


def now_shanghai_iso() -> str:
    return datetime.now(TZ_SHANGHAI).isoformat(timespec="seconds")


def to_shanghai_display(value: str | None) -> str:
    """Convert stored ISO timestamp to 'YYYY-MM-DD HH:MM:SS' in UTC+8."""
    if not value:
        return "-"
    try:
        raw = value.replace("Z", "+00:00")
        dt = datetime.fromisoformat(raw)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        local = dt.astimezone(TZ_SHANGHAI)
        return local.strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return value

