#!/usr/bin/env python3
"""Trace andaike.com homepage「快速贷款」submit → jump URL.

Does NOT send personal info to the live site.
Records intended POST target from the page, then probes redirect
with a phone-free request to observe server Refresh / Location.
"""

from __future__ import annotations

import asyncio
import re
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo

from playwright.async_api import async_playwright

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "reports" / "andaike_jump.txt"
HOME = "http://www.andaike.com/"
DEFAULT_NAME = "张3"
DEFAULT_PHONE = "150123456789"
UA = {"User-Agent": "Mozilla/5.0 AntiBotTester/1.0 (observation-only)"}


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ANN001
        raise urllib.error.HTTPError(newurl, code, msg, headers, fp)


def _http(url: str, data: dict | None = None) -> tuple[int, str, dict[str, str], str]:
    opener = urllib.request.build_opener(_NoRedirect())
    headers = dict(UA)
    headers["Referer"] = HOME
    body = None
    if data is not None:
        body = urllib.parse.urlencode(data).encode()
        headers["Content-Type"] = "application/x-www-form-urlencoded"
    req = urllib.request.Request(url, data=body, headers=headers, method="POST" if data is not None else "GET")
    try:
        with opener.open(req, timeout=20) as resp:
            raw = resp.read().decode("utf-8", "ignore")
            return resp.status, str(resp.url), {k: v for k, v in resp.headers.items()}, raw
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode("utf-8", "ignore") if exc.fp else ""
        return int(exc.code), str(getattr(exc, "url", url) or url), dict(exc.headers or {}), raw


def _extract_refresh(html: str) -> str | None:
    m = re.search(r"content=['\"]?\d+\s*;\s*url=([^'\">]+)", html, re.I)
    return m.group(1).strip() if m else None


async def _read_form_meta(name: str, phone: str) -> dict:
    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=True)
        page = await browser.new_page()
        await page.goto(HOME, wait_until="domcontentloaded", timeout=30000)
        await page.evaluate(
            """() => {
              try { if (window.layer) layer.closeAll(); } catch (e) {}
              document.querySelectorAll('.layui-layer,.layui-layer-shade').forEach(n => n.remove());
            }"""
        )
        await page.fill("input[name=name]", name)
        await page.fill("input[name=phone]", phone)
        await page.fill("input[name=money]", "10")
        await page.fill("input[name=gcode]", "000000")
        await page.evaluate(
            """() => {
              const c = document.getElementById('yhysxy1');
              if (c) c.checked = true;
            }"""
        )
        meta = await page.evaluate(
            """() => {
              const f = document.getElementById('foot_register');
              if (!f) return null;
              const data = {};
              for (const el of f.elements) {
                if (el.name) data[el.name] = el.value;
              }
              return {
                action: f.action,
                method: (f.method || 'post').toUpperCase(),
                hidden_url: data.url || null,
                fields: Object.keys(data),
              };
            }"""
        )
        await browser.close()
        return meta or {}


def main() -> int:
    name = DEFAULT_NAME
    phone = DEFAULT_PHONE
    applied_at = datetime.now(ZoneInfo("Asia/Shanghai")).strftime("%Y-%m-%d %H:%M:%S UTC+8")

    meta = asyncio.run(_read_form_meta(name, phone))
    submit_url = meta.get("action") or "http://www.andaike.com/user/fastApply/"
    hidden_url = meta.get("hidden_url") or "/user/recruit_cpc"

    # Probe redirect using the same hidden url field, without phone/name.
    status, _, headers, html = _http(
        submit_url,
        {
            "url": hidden_url,
            "mortgageType": "2",
            "provinceId": "23",
            "cityId": "0",
            "sex": "2",
            "yhys": "1",
            "money": "10",
        },
    )
    jump = headers.get("Location") or _extract_refresh(html)
    if jump and jump.startswith("/"):
        jump = "http://www.andaike.com" + jump

    # Follow one more hop if same-site intermediate (e.g. /xiaofei/ → ty.andaike.com)
    hop2 = None
    if jump:
        s2, u2, h2, _ = _http(jump)
        hop2 = h2.get("Location")
        if not hop2 and u2 and u2 != jump:
            hop2 = u2

    OUT.parent.mkdir(parents=True, exist_ok=True)
    lines = [
        "安贷客首页「快速贷款」跳转解析",
        f"姓名：{name}",
        f"手机号：{phone}",
        f"申请时间：{applied_at}",
        f"提交步骤：点击「快速贷款」",
        f"提交方式：{meta.get('method', 'POST')}",
        f"提交接口：{submit_url}",
        f"隐藏跳转字段 url：{hidden_url}",
        f"接口响应状态：{status}",
        f"跳转 URL：{jump or '-'}",
    ]
    if hop2:
        lines.append(f"下一跳 URL：{hop2}")
    lines.append("说明：个人信息未向站点提交；跳转由页面表单与无手机号探测确认。")
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(OUT.resolve())
    print(f"跳转 URL：{jump or '-'}")
    if hop2:
        print(f"下一跳 URL：{hop2}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

