#!/usr/bin/env python3
"""Monitor real andaike.com page behavior.

Only writes reports/andaike_jump.txt AFTER the browser actually navigates
to the next page (post captcha + 「快速贷款」). One line:
姓名,手机号,申请时间

Scope: this browser session only — cannot see other visitors.
Does not auto-fill SMS captcha or forge a successful jump.
"""

from __future__ import annotations

import argparse
import asyncio
from datetime import datetime
from pathlib import Path
from urllib.parse import urlparse
from zoneinfo import ZoneInfo

from playwright.async_api import async_playwright

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "reports" / "andaike_jump.txt"
HOME = "http://www.andaike.com/"
DEFAULT_NAME = "张3"
DEFAULT_PHONE = "150123456789"

NEXT_PATH_MARKERS = (
    "/user/recruit_cpc",
    "/user/recruit_Cpc",
    "/user/fastApply",
    "/xiaofei/",
)


def _is_next_page(url: str) -> bool:
    u = (url or "").lower()
    if not u or u.rstrip("/") in {"http://www.andaike.com", "https://www.andaike.com"}:
        return False
    path = urlparse(url).path.lower()
    if path in {"", "/"}:
        return False
    return any(m.lower() in u for m in NEXT_PATH_MARKERS) or (
        "andaike.com" in u and path not in {"", "/"} and "www.andaike.com/" == urlparse(url).netloc + "/"
        and path != "/"
    )


def _is_success_landing(url: str) -> bool:
    """True when left homepage for apply success / recruit / product jump."""
    if not url:
        return False
    low = url.lower()
    host = urlparse(url).netloc.lower()
    path = urlparse(url).path
    if "andaike.com" not in host:
        return True  # external hop counts as jump
    if path in {"", "/"}:
        return False
    markers = ("recruit_cpc", "recruit_Cpc", "fastApply", "xiaofei")
    return any(m.lower() in low for m in markers)


def _write_line(name: str, phone: str, applied_at: str) -> None:
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(f"{name},{phone},{applied_at}\n", encoding="utf-8")


async def _read_form_values(page) -> tuple[str, str]:
    data = await page.evaluate(
        """() => {
          const f = document.getElementById('foot_register');
          if (!f) return {name:'', phone:''};
          const n = f.querySelector('input[name=name]');
          const p = f.querySelector('input[name=phone]');
          return {name: (n && n.value) || '', phone: (p && p.value) || ''};
        }"""
    )
    return (data.get("name") or "").strip(), (data.get("phone") or "").strip()


async def monitor(*, timeout_s: int, name: str, phone: str, headed: bool) -> int:
    print(f"监控真实页面: {HOME}")
    print("条件: 验证码填写后点击「快速贷款」，且浏览器确实进入下一页，才写入 txt")
    print(f"超时: {timeout_s}s · 仅本浏览器会话\n")

    jumped = asyncio.Event()
    captured: dict[str, str] = {"name": name, "phone": phone}
    last_url = {"value": ""}

    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=not headed)
        context = await browser.new_context(
            user_agent="Mozilla/5.0 AntiBotTester/1.0 (authorized-observation)"
        )
        page = await context.new_page()

        async def on_nav(frame) -> None:
            if frame != page.main_frame:
                return
            url = frame.url
            last_url["value"] = url
            print(f"[nav] {url}")
            if _is_success_landing(url):
                # Prefer values already snapped at submit; else read if still on form
                n, ph = captured["name"], captured["phone"]
                if not n or not ph:
                    try:
                        n2, ph2 = await _read_form_values(page)
                        n = n or n2
                        ph = ph or ph2
                    except Exception:
                        pass
                applied_at = datetime.now(ZoneInfo("Asia/Shanghai")).strftime(
                    "%Y-%m-%d %H:%M:%S UTC+8"
                )
                captured["name"] = n or name
                captured["phone"] = ph or phone
                captured["applied_at"] = applied_at
                captured["jump_url"] = url
                jumped.set()

        page.on("framenavigated", lambda f: asyncio.create_task(on_nav(f)))

        # Snapshot form fields when POST to fastApply starts (before navigation)
        async def on_request(req) -> None:
            if req.method != "POST":
                return
            if "/user/fastApply" not in req.url:
                return
            print(f"[post] {req.url}")
            try:
                n, ph = await _read_form_values(page)
                if n:
                    captured["name"] = n
                if ph:
                    captured["phone"] = ph
                print(f"[form] name={captured['name']!r} phone={captured['phone']!r}")
            except Exception as exc:
                print(f"[form] read failed: {exc}")

        page.on("request", lambda r: asyncio.create_task(on_request(r)))

        await page.goto(HOME, wait_until="domcontentloaded", timeout=45000)
        await page.evaluate(
            """() => {
              try { if (window.layer) layer.closeAll(); } catch (e) {}
              document.querySelectorAll('.layui-layer,.layui-layer-shade').forEach(n => n.remove());
            }"""
        )
        # Prefill visible fields except captcha — real jump still needs real SMS code
        try:
            await page.fill("input[name=name]", name)
            await page.fill("input[name=phone]", phone)
            await page.fill("input[name=money]", "10")
            await page.evaluate(
                """() => {
                  const c = document.getElementById('yhysxy1');
                  if (c) c.checked = true;
                }"""
            )
        except Exception as exc:
            print(f"[warn] prefill: {exc}")

        print("已打开真实页面。监听中：仅当发生真实跳转才写文件……")
        try:
            await asyncio.wait_for(jumped.wait(), timeout=timeout_s)
        except asyncio.TimeoutError:
            print("超时：未观测到进入下一页（通常因未完成验证码提交）。未写入输出。")
            await context.close()
            await browser.close()
            return 1

        _write_line(captured["name"], captured["phone"], captured["applied_at"])
        print(f"已确认跳转: {captured.get('jump_url')}")
        print(OUT.resolve())
        print(OUT.read_text(encoding="utf-8").rstrip())
        await context.close()
        await browser.close()
        return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Monitor real andaike jump, then write CSV line")
    parser.add_argument("--timeout", type=int, default=600, help="seconds to watch for real jump")
    parser.add_argument("--name", default=DEFAULT_NAME)
    parser.add_argument("--phone", default=DEFAULT_PHONE)
    parser.add_argument("--headless", action="store_true", help="run headless (default headed)")
    args = parser.parse_args(argv)
    return asyncio.run(
        monitor(
            timeout_s=args.timeout,
            name=args.name,
            phone=args.phone,
            headed=not args.headless,
        )
    )


if __name__ == "__main__":
    raise SystemExit(main())

