/**
 * Embedded monitor for andaike.com homepage form.
 * Captures form fields on submit and reports real navigation / jump URL
 * to the local collector (127.0.0.1).
 */
(function () {
  if (window.__ADK_EMBED_MONITOR__) return;
  window.__ADK_EMBED_MONITOR__ = true;

  var COLLECTOR = "http://127.0.0.1:8791/event";
  var lastPayload = null;

  function post(event, extra) {
    var body = Object.assign(
      {
        event: event,
        page_url: location.href,
        ts: Date.now(),
      },
      extra || {}
    );
    try {
      if (navigator.sendBeacon) {
        navigator.sendBeacon(COLLECTOR, JSON.stringify(body));
      } else {
        fetch(COLLECTOR, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(body),
          mode: "cors",
          keepalive: true,
        }).catch(function () {});
      }
    } catch (e) {}
  }

  function readForm() {
    var f = document.getElementById("foot_register");
    if (!f) return null;
    var data = {};
    for (var i = 0; i < f.elements.length; i++) {
      var el = f.elements[i];
      if (!el.name) continue;
      if (el.type === "radio" && !el.checked) continue;
      if (el.type === "checkbox" && !el.checked) continue;
      data[el.name] = el.value;
    }
    return data;
  }

  function snapshot() {
    var data = readForm() || {};
    lastPayload = {
      name: data.name || "",
      phone: data.phone || "",
      money: data.money || "",
      gcode: data.gcode || "",
      hidden_url: data.url || "",
      action: (document.getElementById("foot_register") || {}).action || "",
    };
    return lastPayload;
  }

  function onSubmit() {
    var snap = snapshot();
    post("form_submit", {
      name: snap.name,
      phone: snap.phone,
      money: snap.money,
      has_gcode: !!(snap.gcode && String(snap.gcode).length > 0),
      hidden_url: snap.hidden_url,
      action: snap.action,
    });
  }

  function bindForm() {
    var f = document.getElementById("foot_register");
    if (!f || f.__adkBound) return;
    f.__adkBound = true;
    f.addEventListener("submit", onSubmit, true);
    var btn = f.querySelector('input[type=submit],button[type=submit]');
    if (btn) btn.addEventListener("click", onSubmit, true);
  }

  // Capture jump URL when leaving homepage / landing on next page
  function reportJump(reason) {
    var snap = lastPayload || snapshot() || {};
    post("page_jump", {
      reason: reason,
      jump_url: location.href,
      name: snap.name || "",
      phone: snap.phone || "",
      money: snap.money || "",
      hidden_url: snap.hidden_url || "",
    });
  }

  var path = location.pathname || "/";
  var isLanding =
    /recruit_cpc|recruit_Cpc|fastApply|xiaofei/i.test(location.href) ||
    (location.host.indexOf("andaike.com") >= 0 && path !== "/");

  if (isLanding) {
    reportJump("landed");
  } else {
    post("monitor_ready", { host: location.host, path: path });
    bindForm();
    setInterval(bindForm, 1500);
    window.addEventListener("beforeunload", function () {
      if (lastPayload) reportJump("beforeunload");
    });
    // SPA-ish / meta refresh may change location without full unload in some cases
    var lastHref = location.href;
    setInterval(function () {
      if (location.href !== lastHref) {
        lastHref = location.href;
        if (/recruit_cpc|recruit_Cpc|fastApply|xiaofei/i.test(lastHref)) {
          reportJump("location_change");
        }
      }
    }, 400);
  }
})();

